using System.Reflection;
using System.Text.Json;
using System.Windows;
using System.Windows.Threading;
using VisionEditor;
using VisionEditor.Core;
using VisionFramework;
using VisionPluginContracts;
using VisionPlugins.BranchString;
static class Program {
 const BindingFlags Private=BindingFlags.NonPublic|BindingFlags.Instance;static int checks;
 static T Field<T>(object value,string name)=>(T)value.GetType().GetField(name,Private)!.GetValue(value)!;static object? Call(object value,string name,params object[] args)=>value.GetType().GetMethod(name,Private)!.Invoke(value,args);
 static void Check(bool condition,string reason){if(!condition)throw new Exception(reason);Console.WriteLine($"PASS {++checks}: {reason}");}static void Pump()=>Application.Current.Dispatcher.Invoke(()=>{},DispatcherPriority.ApplicationIdle);
 static void Wait(Task task){var frame=new DispatcherFrame();_=task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(()=>frame.Continue=false));if(!task.IsCompleted)Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();Pump();}
 [STAThread]static int Main(){MainWindow? shell=null;try{_=new Application();SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Application.Current.Dispatcher));shell=new MainWindow{ShowInTaskbar=false,ShowActivated=false};shell.Show();Pump();Run(shell);Console.WriteLine($"PASS {checks} real BranchString MainWindow host checks");return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}finally{shell?.Close();Application.Current?.Shutdown();}}
 static void Run(MainWindow shell){var plugins=Field<ToolPluginRegistry>(shell,"plugins");var plugin=plugins.Find(BranchStringPlugin.Id) as BranchStringPlugin;Check(plugin is not null,"actual MainWindow registers BranchString plugin");using var catalog=JsonDocument.Parse(System.IO.File.ReadAllText("src/VisionEditor/tool-catalog.json"));var entry=catalog.RootElement.GetProperty("Groups").EnumerateArray().SelectMany(g=>g.GetProperty("Items").EnumerateArray()).Single(i=>i.GetProperty("Id").GetString()=="BranchStringCpmL");Check(entry.GetProperty("ModuleId").GetString()==BranchStringPlugin.Id,"existing catalog directory identity maps to real BranchString implementation");var doc=Field<GraphEditorDocument>(shell,"doc");doc.NewSolution();var modules=Field<ModuleRegistry>(shell,"modules");var sink=new ModuleDescriptor("test.branch-string-sink","1","Sink",[],[],[]);modules.Register(sink,()=>new Sink(sink));string root=doc.AddNode(BranchStringPlugin.Id,"1.0.0",0,0),left=doc.AddNode(sink.Id,"1",150,0),right=doc.AddNode(sink.Id,"1",150,100);NodeDocument Node()=>doc.CurrentProcedure.Nodes.Single(n=>n.Id==root);string Rows()=>Node().Parameters["ModuleInfoList"].GetString()!;doc.ConnectExecution(root,left);doc.ConnectExecution(root,right);string defaults=left+"##0$"+right+"##0$";Check(Rows()==defaults,"real topology hook creates actual empty-string defaults");
  ToolEditorContext Context()=> (ToolEditorContext)Call(shell,"ConnectToolEditorServices",new ToolEditorContext(Node(),doc.BaseDirectory,_=>{},_=>throw new InvalidOperationException()),root)!;
  void Bind(string value){var result=Context().ConfigurationSubscriptions!.Bind(new(ConfigurationSubscriptionDomain.InputIo,"StringA","string"),new(new ConfigurationConstantReference("string",value),ConfigurationSubscriptionIndex.All));Check(result.Status==ConfigurationSubscriptionStatus.Available,"actual typed string binding: "+JsonSerializer.Serialize(value));}
  NodeRunRecord RunGraph(){Wait((Task)Call(shell,"RunProcedure",doc.CurrentProcedureId)!);return Field<Dictionary<string,NodeRunRecord>>(shell,"results")[root];}
  Bind("");var before=RunGraph();Check(before.Outputs["ModuStatus"].As<long>()==1&&before.Outputs["BranchMatch"].As<string>()=="NodeId:"+left+";NodeId:"+right+";","actual empty input has outLen1 and selects both empty defaults");
  string save=System.IO.Path.GetFullPath("analysis/b-string/host-solution/branch-string.vsolution");System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(save)!);doc.Save(save);Check(Rows()==defaults,"saving live document does not prematurely invoke native Load setter");Check(RunGraph().Outputs["ModuStatus"].As<long>()==1,"same live defaults still match empty input after Save");doc.Load(save);Check(Rows()==left+"#0#0$"+right+"#0#0$","actual MainWindow Load provider roundtrips empty default into text0");Check(RunGraph().Outputs["BranchMatch"].As<string>()=="No Module","restored text0 no longer matches empty input");Bind("0");Check(RunGraph().Outputs["ModuStatus"].As<long>()==1,"restored native text0 matches literal0");
  Call(shell,"OpenToolConfiguration",root);var window=(ToolConfigurationModelWindow)Field<ToolConfigurationWindowHost>(shell,"toolConfigurationWindows").Current!;var session=Field<ToolConfigurationSession>(window,"session");Check(window.ConfigurationView.Diagnostics.Count==0,"actual host creates original ListParamStr and shared HeadBar");Check(session.State.Nodes.Count(n=>n.Element.Tag=="BottomCommand")==1&&!session.State.Nodes.Any(n=>n.Element.Tag.Contains("Execute")||n.Element.Tag.Contains("Reset")),"actual source configuration has Confirm only, no invented Execute or Reset");session.State.CommitUser("ModuleInfoList",right+"#beta#0$"+left+"#alpha#0$");Check(Rows()==right+"#beta#0$"+left+"#alpha#0$","real source table edit persists text/flags in configured order");window.Close();Pump();Bind("alpha");var selected=RunGraph();Check(selected.Outputs["BranchMatch"].As<string>()=="NodeId:"+left+";"&&Field<Dictionary<string,NodeRunRecord>>(shell,"results")[right].Status==NodeRunStatus.Skipped,"real workflow executes only selected text branch");var scope=Field<ModuleExecutionScope>(shell,"executionScope").ForProcedure(doc.CurrentProcedureId);var display=plugin!.LastDisplay(Node(),doc.BaseDirectory,scope);Check(display?.Text=="Input Params:alpha , Branch RunWay:NodeId:"+left+"; ","actual scoped display follows original Show Text mapping");Check(display!.RecordText=="Module Status:1;Branch MatchWay:NodeId:"+left+";","Data Record uses its separate source content template");
  var debug=(ToolEditorContext)Call(shell,"CreateToolEditorContext",root)!;var task=debug.Run(Node().Parameters.ToDictionary(p=>p.Key,p=>p.Value.Clone()));Wait(task);Check(task.Result.Outputs["BranchMatch"].As<string>()=="NodeId:"+left+";","actual host NodeDebug run observes original successors");Check(plugin.LastDisplay(Node(),doc.BaseDirectory,scope)?.Text.Contains("NodeId:"+left+";")==true,"actual debug uses same procedure scope display owner");if(debug.Session is IAsyncDisposable disposable)Wait(disposable.DisposeAsync().AsTask());
  var copied=doc.PasteNodes(doc.CopyNodes([root,left]),350,200);var copy=doc.CurrentProcedure.Nodes.Single(n=>copied.Contains(n.Id)&&n.ModuleId==BranchStringPlugin.Id);var target=doc.CurrentProcedure.Nodes.Single(n=>copied.Contains(n.Id)&&n.ModuleId==sink.Id);Check(copy.Parameters["ModuleInfoList"].GetString()==target.Id+"#alpha#0$","actual Paste maps copied target and preserves text/flag");var single=doc.PasteNodes(doc.CopyNodes([root]),650,200);Check(doc.CurrentProcedure.Nodes.Single(n=>n.Id==single.Single()).Parameters["ModuleInfoList"].GetString()=="","single-node Paste has no stale target IDs");doc.Undo();doc.Redo();Check(doc.CurrentProcedure.Nodes.Single(n=>n.Id==single.Single()).Parameters["ModuleInfoList"].GetString()=="","Undo/Redo replays prepared copy without fake topology changes");doc.DisconnectExecution(new(root,right));Check(Rows()==left+"#alpha#0$","real disconnect retains surviving text/flag");var old=Node();doc.DeleteNodes([root]);Check(plugin.LastDisplay(old,doc.BaseDirectory,scope) is null,"node removal clears procedure-owned display snapshot");}
 sealed class Sink(ModuleDescriptor descriptor):IModule{public ModuleDescriptor Descriptor=>descriptor;public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext context,CancellationToken cancellationToken)=>ValueTask.FromResult(new ModuleResult(ModuleStatus.Success,new Dictionary<string,PortValue>()));}
